  catLabel = em ? decodeURIComponent(em[1].replace(/\+/g, ' ')) : pin.catSlug;
}
var pinUrl = SITE + '/api/pin?title=' + encodeURIComponent(pin.title) + '&eyebrow=' + encodeURIComponent(catLabel) + '&img=' + encodeURIComponent(pin.coverAbs);
if (catLabel === 'Printables') { pinUrl = pinUrl + '&badge=' + encodeURIComponent('FREE PRINTABLE'); }
  pinUrl = pinUrl + '&t=' + Date.now();
return [{ json: { slug: slug, title: pin.title, postUrl: postUrl, pinUrl: pinUrl, pinText: pin.pinText, keyword: pin.keyword } }];
